class Solution:
    def evenOddBit(self, n: int) -> List[int]:
        even = odd = 0
        i = 0
        while n >> i:
            if (n >> i) & 1:
                if i % 2 == 0:
                    even += 1
                else:
                    odd += 1
            i += 1
        return [even, odd]

c.cpp:
class Solution {
public:
    vector<int> evenOddBit(int n) {
        int even = 0, odd = 0;
        for (int i = 0; (n >> i) > 0; i++)
            if ((n >> i) & 1) { if (i % 2 == 0) even++; else odd++; }
        return {even, odd};
    }
};

